#include <iostream>
#include <queue>

using namespace std;

class Node {
public:
    int value;
    Node(int val) : value(val) {}
};

class WaitingQueue {
private:
    queue<Node*> q;

public:
    void enqueue(Node* node) {
        q.push(node);
    }

    void dequeue() {
        if (!q.empty()) {
            Node* node = q.front();
            q.pop();
            cout << "Processing node with value: " << node->value << endl;
            delete node; // Clean up memory
        } else {
            cout << "Queue is empty." << endl;
        }
    }

    bool isEmpty() {
        return q.empty();
    }

    void displayQueue() {
        queue<Node*> temp = q; // Copy to display
        cout << "Current queue: ";
        while (!temp.empty()) {
            cout << temp.front()->value << " ";
            temp.pop();
        }
        cout << endl;
    }
};

int main() {
    WaitingQueue wq;
    wq.enqueue(new Node(1));
    wq.enqueue(new Node(2));
    wq.enqueue(new Node(3));

    wq.displayQueue();
    wq.dequeue();
    wq.displayQueue();

    return 0;
}
```

This code defines a `Node` class and a `WaitingQueue` class that manages the queue of nodes. The `enqueue` method adds a node to the queue, while the `dequeue` method processes the front node. The `displayQueue` method shows the current state of the queue.

